//! Port of Symfony\Component\Mime\MimeTypes.php, with
//! MimeTypesInterface.php and MimeTypeGuesserInterface.php: MIME types
//! and their file extensions, and the registered guessers.
//!
//! The extension tables are upstream's `MAP` and `REVERSE_MAP`
//! (`map.rs`, generated by `scripts/gen-mime-types.py`). Lookups try the
//! text as given, then in lowercase (ASCII, as PHP 8's `strtolower()`).
//!
//! Not ported: `FileinfoMimeTypeGuesser` (PHP's `finfo`, the libmagic
//! copy bundled with PHP; PLAN.md decision 18). `new()` registers only
//! `FileBinaryMimeTypeGuesser`, the guesser upstream asks after finfo;
//! callers may register their own with [`MimeTypes::register_guesser`].
//!
//! Symfony source copyright (c) Fabien Potencier; distributed under MIT.
//!
//! Upstream: symfony/mime MimeTypes.php MimeTypesInterface.php MimeTypeGuesserInterface.php

use std::{
    collections::HashMap,
    sync::{Arc, OnceLock, RwLock},
};

use crate::{
    exception::{Class, Error, Result},
    file_binary_mime_type_guesser::FileBinaryMimeTypeGuesser,
    map,
};

/// `MimeTypeGuesserInterface`: guesses the MIME type of a file.
pub trait MimeTypeGuesser: Send + Sync + std::fmt::Debug {
    /// `isGuesserSupported()`: whether this guesser can run here.
    fn is_guesser_supported(&self) -> bool;

    /// `guessMimeType($path)`: the MIME type, or `None` (PHP's null) when
    /// it is not known.
    ///
    /// Errors are `InvalidArgumentException` for a file that does not
    /// exist or cannot be read, `LogicException` when the guesser is not
    /// supported.
    fn guess_mime_type(&self, path: &[u8]) -> Result<Option<String>>;
}

/// `new MimeTypes($map)`.
#[derive(Debug)]
pub struct MimeTypes {
    extensions: HashMap<String, Vec<String>>,
    mime_types: HashMap<String, Vec<String>>,
    /// Most recently registered first.
    guessers: Vec<Arc<dyn MimeTypeGuesser>>,
}

impl Default for MimeTypes {
    fn default() -> Self {
        Self::new(Vec::<(String, Vec<String>)>::new())
    }
}

/// A table from upstream's constants, built once.
type Table = HashMap<&'static str, &'static [&'static str]>;

fn table(rows: &'static [(&'static str, &'static [&'static str])]) -> Table {
    rows.iter().copied().collect()
}

fn forward() -> &'static Table {
    static MAP: OnceLock<Table> = OnceLock::new();
    MAP.get_or_init(|| table(map::MAP))
}

fn reverse() -> &'static Table {
    static MAP: OnceLock<Table> = OnceLock::new();
    MAP.get_or_init(|| table(map::REVERSE_MAP))
}

fn owned(values: &[&str]) -> Vec<String> {
    values.iter().map(|v| (*v).to_string()).collect()
}

/// `$custom[$key] ?? $custom[strtolower($key)] ?? CONST[$key] ??
/// CONST[strtolower($key)] ?? []`.
fn lookup(custom: &HashMap<String, Vec<String>>, table: &Table, key: &str) -> Vec<String> {
    let lower = key.to_ascii_lowercase();
    if !custom.is_empty()
        && let Some(found) = custom.get(key).or_else(|| custom.get(&lower))
    {
        return found.clone();
    }
    table
        .get(key)
        .or_else(|| table.get(lower.as_str()))
        .map(|v| owned(v))
        .unwrap_or_default()
}

/// `MimeTypes::$default`.
static DEFAULT: RwLock<Option<Arc<MimeTypes>>> = RwLock::new(None);

impl MimeTypes {
    /// `new MimeTypes($map)`: `$map` lists MIME types with their
    /// extensions; it is asked before upstream's tables.
    pub fn new<M, E>(map: impl IntoIterator<Item = (M, E)>) -> Self
    where
        M: Into<String>,
        E: IntoIterator,
        E::Item: Into<String>,
    {
        let mut extensions: HashMap<String, Vec<String>> = HashMap::new();
        let mut mime_types: HashMap<String, Vec<String>> = HashMap::new();
        for (mime_type, exts) in map {
            let mime_type = mime_type.into();
            let exts: Vec<String> = exts.into_iter().map(Into::into).collect();
            for extension in &exts {
                mime_types
                    .entry(extension.clone())
                    .or_default()
                    .push(mime_type.clone());
            }
            // a key given twice keeps its last list, as a PHP array does
            extensions.insert(mime_type, exts);
        }
        let mut types = Self {
            extensions,
            mime_types,
            guessers: Vec::new(),
        };
        types.register_guesser(Arc::new(FileBinaryMimeTypeGuesser::new()));
        types
    }

    /// `MimeTypes::setDefault($default)`.
    pub fn set_default(default: Arc<MimeTypes>) {
        let mut slot = DEFAULT.write().unwrap_or_else(|e| e.into_inner());
        *slot = Some(default);
    }

    /// `MimeTypes::getDefault()`: the shared instance, created on first
    /// use.
    pub fn get_default() -> Arc<MimeTypes> {
        if let Some(default) = DEFAULT.read().unwrap_or_else(|e| e.into_inner()).as_ref() {
            return default.clone();
        }
        let mut slot = DEFAULT.write().unwrap_or_else(|e| e.into_inner());
        slot.get_or_insert_with(|| Arc::new(MimeTypes::default()))
            .clone()
    }

    /// `registerGuesser($guesser)`: the last registered guesser is asked
    /// first.
    pub fn register_guesser(&mut self, guesser: Arc<dyn MimeTypeGuesser>) {
        self.guessers.insert(0, guesser);
    }

    /// `getExtensions($mimeType)`: the extensions, most common first.
    pub fn get_extensions(&self, mime_type: &str) -> Vec<String> {
        lookup(&self.extensions, forward(), mime_type)
    }

    /// `getMimeTypes($ext)`: the MIME types, most common first.
    pub fn get_mime_types(&self, ext: &str) -> Vec<String> {
        lookup(&self.mime_types, reverse(), ext)
    }
}

impl MimeTypeGuesser for MimeTypes {
    fn is_guesser_supported(&self) -> bool {
        self.guessers.iter().any(|g| g.is_guesser_supported())
    }

    /// Asks each supported guesser, last registered first, until one
    /// answers.
    fn guess_mime_type(&self, path: &[u8]) -> Result<Option<String>> {
        for guesser in &self.guessers {
            if !guesser.is_guesser_supported() {
                continue;
            }
            if let Some(mime_type) = guesser.guess_mime_type(path)? {
                return Ok(Some(mime_type));
            }
        }
        if !self.is_guesser_supported() {
            return Err(Error::new(
                Class::Logic,
                "Unable to guess the MIME type as no guessers are available (have you enabled the php_fileinfo extension?).",
            ));
        }
        Ok(None)
    }
}
